import {useRef, useState} from 'react'
import {useLayoutEffect} from '@github-ui/use-layout-effect'

export type MeasureFn = (text: string) => number

export interface TruncateOptions {
  delimiter?: string
  preferWords?: boolean
}

const DEFAULT_DELIMITER = '…'

export function truncateByWordsToWidth(
  text: string,
  maxWidth: number,
  measure: MeasureFn,
  delimiter = DEFAULT_DELIMITER,
) {
  if (!text) return ''
  const words = text.trim().split(/\s+/)
  const full = words.join(' ')
  if (measure(full) <= maxWidth) return full
  let lo = 0
  let hi = words.length
  let best = ''
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2)
    const candidate = words.slice(0, mid).join(' ') + delimiter
    if (measure(candidate) <= maxWidth) {
      best = candidate
      lo = mid + 1
    } else {
      hi = mid
    }
  }
  return best || delimiter
}

export function truncateToWidth(
  text: string,
  maxWidth: number,
  measure: MeasureFn,
  {delimiter = DEFAULT_DELIMITER}: TruncateOptions = {},
) {
  if (!text) return ''
  if (measure(text) <= maxWidth) return text
  const byWords = truncateByWordsToWidth(text, maxWidth, measure, delimiter)
  if (measure(byWords) <= maxWidth) return byWords
}

export function useTruncatedText(text: string, maxWidth: number, options: TruncateOptions = {}) {
  const [truncated, setTruncated] = useState(text)
  const fontElementRef = useRef<HTMLElement | null>(null)
  const measurerRef = useRef<HTMLSpanElement | null>(null)

  useLayoutEffect(() => {
    if (typeof window === 'undefined') return
    if (!measurerRef.current) {
      const span = document.createElement('span')
      span.style.visibility = 'hidden'
      span.style.position = 'absolute'
      span.style.whiteSpace = 'nowrap'
      span.style.left = '-9999px'
      span.style.top = '0'
      document.body.appendChild(span)
      measurerRef.current = span
    }

    const measurer = measurerRef.current
    if (!measurer) return
    const source = fontElementRef.current
    if (source) {
      const cs = window.getComputedStyle(source)
      const props = [
        'fontFamily',
        'fontSize',
        'fontWeight',
        'fontStyle',
        'letterSpacing',
        'wordSpacing',
        'textTransform',
        'textRendering',
      ] as const
      const styleTarget = measurer.style as unknown as Record<string, string>
      const styleSource = cs as unknown as Record<string, string>
      for (const p of props) {
        const val = styleSource[p]
        if (typeof val === 'string') styleTarget[p] = val
      }
    }

    const measure: MeasureFn = value => {
      measurer.textContent = value
      return measurer.getBoundingClientRect().width
    }

    const next = truncateToWidth(text, maxWidth, measure, options)
    setTruncated(next ?? text)
  }, [text, maxWidth, options])

  return {ref: fontElementRef, truncated}
}
