import {useEffect, useId, useMemo, useRef, useState} from 'react'
import styles from './CompactStyleEdge.module.css'
import {useEdgeStatus, type Status} from '../../../state/lenses'
import {clsx} from 'clsx'
import {useTheme} from '@primer/styled-react'
import {useIsSafari} from '@github-ui/use-sticky-header/useIsSafari'

interface PipelineEdgeProps {
  path: string
  source: string
  target: string
  isProcessing?: boolean
  active?: boolean
  faded?: boolean
  strokeWidth?: number // Used to differentiate between top and bottom edges
  showGap?: boolean // Whether to show a gap in the edge
}

const isIdleOrProcessing = (status: Status): boolean => {
  return status === 'IDLE' || status === 'PROCESSING'
}

const getMaskStrokeWidth = (status: Status, strokeWidth: number): number => {
  return status === 'PROCESSING' ? strokeWidth * 1.25 : strokeWidth * 0.75
}

const getCompletedAddOnStrokeColor = (active: boolean): string => {
  return active ? 'var(--borderColor-success-emphasis)' : 'var(--borderColor-success-muted)'
}

const getIdleFillColor = (theme: {colorScheme?: string}): string => {
  return theme.colorScheme?.includes('dark') || theme.colorScheme?.includes('night') ? '#CCC' : '#333'
}

// Helper functions for styling logic
const getStrokeColor = (status: Status, active: boolean): string => {
  if (active) {
    if (status === 'IDLE' || status === 'PROCESSING') return 'var(--borderColor-emphasis)'
    if (status === 'ERROR') return 'var(--borderColor-attention-emphasis)'
    return 'var(--borderColor-success-muted)'
  } else {
    if (status === 'IDLE' || status === 'PROCESSING') return 'var(--borderColor-default)'
    if (status === 'ERROR') return 'var(--borderColor-attention-muted)'
    return 'var(--borderColor-success-muted)'
  }
}

const getEdgeClassNames = (status: Status): string => {
  return clsx(
    styles.edge,
    (status === 'IDLE' || status === 'PROCESSING') && styles.edgeDefault,
    status === 'ERROR' && styles.edgeError,
    status === 'COMPLETED' && styles.edgeCompleted,
  )
}

const getEdgeAddonClassNames = (status: Status): string => {
  return clsx(
    styles.edgeAddon,
    status === 'IDLE' && styles.edgeIdleAddon,
    status === 'PROCESSING' && styles.edgeProcAddon,
  )
}

const getAnimationProps = (status: Status, delay: string) => {
  return {
    radius: status === 'IDLE' ? 25 : 30,
    duration: status === 'IDLE' ? '6s' : '2s',
    begin: status === 'IDLE' ? delay : '0s',
  }
}

export const CompactStyleEdge: React.FC<PipelineEdgeProps> = ({
  path,
  source,
  target,
  active = false,
  faded = false,
  showGap = true,
  strokeWidth = 2,
}) => {
  const id = useId()
  const theme = useTheme()
  const status: Status = useEdgeStatus(source, target)

  const maskId = `mask-${id}`
  const pathId = `path-${id}`
  const gradIdle = `idle-grad-${id}`
  const gradProc = `proc-grad-${id}`
  const idleFillColor = getIdleFillColor(theme)

  const completedPathRef = useRef<SVGPathElement>(null)
  const [dashLength, setDashLength] = useState<number>(0)
  const isSafari = useIsSafari()

  useEffect(() => {
    if (status === 'COMPLETED' && completedPathRef.current) {
      const length = Math.ceil(completedPathRef.current.getTotalLength())
      setDashLength(length)
    }
  }, [status, path, isSafari])

  const delay = useMemo(() => `${1 + Math.random() * 2}s`, [])

  const renderEdgeAddOn = () => {
    if (isIdleOrProcessing(status)) {
      const animationProps = getAnimationProps(status, delay)

      return (
        <g mask={`url(#${maskId})`} className={getEdgeAddonClassNames(status)}>
          <circle
            r={animationProps.radius}
            fill={`url(#${status === 'IDLE' ? gradIdle : gradProc})`}
            style={{opacity: faded ? 0.75 : 1}}
          >
            <animateMotion
              rotate="auto"
              dur={animationProps.duration}
              begin={animationProps.begin}
              repeatCount="indefinite"
            >
              <mpath href={`#${pathId}`} />
            </animateMotion>
          </circle>
        </g>
      )
    }

    if (status === 'COMPLETED')
      return (
        <path
          d={path}
          ref={completedPathRef}
          strokeWidth={strokeWidth}
          fill="none"
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeDasharray={isSafari ? undefined : dashLength}
          strokeDashoffset={isSafari ? undefined : dashLength}
          stroke={getCompletedAddOnStrokeColor(active)}
          className={styles.edgeCompletedAddOn}
          style={{
            opacity: faded ? 0.35 : 1,
          }}
        />
      )
  }

  return (
    <g>
      <defs>
        {/* For Idle */}
        <linearGradient id={gradIdle} x1="0%" x2="100%" y1="0%" y2="0%">
          <stop stopColor={idleFillColor} stopOpacity="0" offset="0%" />
          <stop stopColor={idleFillColor} stopOpacity="0.6" offset="100%" />
        </linearGradient>

        {/* For Processing */}
        <linearGradient id={gradProc} x1="0%" x2="100%" y1="0%" y2="0%">
          <stop stopColor="#007bff" stopOpacity="0" offset="0%" />
          <stop stopColor="#007bff" stopOpacity="1" offset="100%" />
        </linearGradient>

        <mask id={maskId}>
          <path
            d={path}
            stroke="white"
            strokeWidth={getMaskStrokeWidth(status, strokeWidth)}
            fill="none"
            strokeLinecap="round"
          />
        </mask>
      </defs>

      {showGap && (
        <path
          d={path}
          id={`${pathId}-bg`}
          className={clsx(styles.edgeBackground)}
          strokeWidth={strokeWidth * 2}
          fill="none"
          aria-hidden="true"
        />
      )}

      <path
        d={path}
        id={pathId}
        className={getEdgeClassNames(status)}
        style={{
          opacity: faded ? 0.75 : 1,
          stroke: getStrokeColor(status, active),
        }}
        strokeWidth={strokeWidth}
        fill="none"
      />
      {renderEdgeAddOn()}
    </g>
  )
}

try{ CompactStyleEdge.displayName ||= 'CompactStyleEdge' } catch {}