import {useMutation, useQueryClient} from '@github-ui/react-query'
import {useLoopsService} from '../../contexts/LoopsServiceProvider'
import type {Execution} from '../../types/execution'
import {executionQueryKey} from '../queries/use-execution'
import {useLoopID} from '../../state/lenses'

export function useCreateExecution() {
  const queryClient = useQueryClient()
  const service = useLoopsService()
  const loopID = useLoopID()

  return useMutation({
    mutationFn: async ({execution, version}: {execution?: Partial<Execution>; version: string}) => {
      if (!loopID) throw new Error('Existing loop is required to create an execution')

      const result = await service.createExecution(loopID, version, execution as Execution | undefined)
      if (!result.success) throw new Error(result.error)
      return result.data
    },
    onSuccess: newExecution => {
      if (loopID) {
        queryClient.setQueryData(executionQueryKey(loopID, newExecution.loopVersion), newExecution)
      }
    },
  })
}
