import {useLayoutEffect} from '@github-ui/use-layout-effect'
import {useCallback, useRef} from 'react'

/**
 * Stable callback hook to avoid losing a callback reference across re-renders.
 * Returns a function with stable identity whose implementation is always the latest.
 * Clears reference on unmount.
 */
export function useStableCallback<A extends unknown[], R>(fn: (...args: A) => R) {
  const ref = useRef<((...args: A) => R) | null>(fn)
  useLayoutEffect(() => {
    ref.current = fn
    return () => {
      ref.current = null
    }
  }, [fn])
  return useCallback((...args: A) => ref.current?.(...args), [])
}
