import {useQueryClient} from '@github-ui/react-query'
import {useLoopID} from '../state/lenses'
import type {Loop} from '../types/app'
import {getLoopQueryKey} from './queries/use-loop'
import {useLoopsStateLens} from '../contexts/LoopsStateProvider'

/**
 * Hook that returns a function to get loop data from the react-query cache.
 * This is useful for components that need to access the loop data without triggering a refetch.
 * Typically this will be in callback functions.
 */
export function useGetLoop() {
  const queryClient = useQueryClient()
  const loopID = useLoopID()
  const loopVersion = useLoopsStateLens(l => l?.version)

  const getLoop = (version: string = loopVersion) => {
    if (!loopID) return null
    return queryClient.getQueryData<Loop | null>(getLoopQueryKey(loopID, version))
  }

  return {
    getLoop,
  }
}
