import {CommentIcon} from '@primer/octicons-react'
import {IconButton} from '@primer/react'
import {sendEvent} from '@github-ui/hydro-analytics'
import {useLoopLens} from '../../hooks/use-loop-lens'
import {useAddLoopNodeReference} from '../../hooks/use-add-loop-node-reference'
import {nodeDefinition} from '../../state/lenses'

interface NodeReferenceButtonProps {
  className?: string
  nodeId: string
}

export function NodeReferenceButton({className, nodeId}: NodeReferenceButtonProps) {
  const {toggleLoopNodeReference, isNodeReferenced} = useAddLoopNodeReference()
  const nodeTitle = useLoopLens(loop => nodeDefinition(nodeId, loop)?.title)
  const isReferenced = nodeTitle ? isNodeReferenced(nodeId, nodeTitle) : false

  const handleReferenceInChat = () => {
    if (!nodeTitle) return

    // Send analytics event for hover button click
    sendEvent('dotcom_chat.activate', {
      target: 'LOOP_NODE_REFERENCE_HOVER_BUTTON',
      mode: 'loops',
    })

    toggleLoopNodeReference(nodeId, nodeTitle, 'nodeHoverButton')
  }

  return (
    <IconButton
      aria-label={isReferenced ? 'Remove this node from chat references' : 'Reference this node in chat'}
      className={className}
      icon={CommentIcon}
      size="small"
      onClick={handleReferenceInChat}
    />
  )
}

try{ NodeReferenceButton.displayName ||= 'NodeReferenceButton' } catch {}