import {useState, type ChangeEvent} from 'react'
import {Dialog, FormControl} from '@primer/react'
import {useSaveLoop} from '../hooks/mutations/use-save-loop'
import {TextInput} from './controls/TextInput'
import {TextArea} from './controls/TextArea'
import styles from './RenameDialog.module.css'
import {useLoopLens} from '../hooks/use-loop-lens'
import {useGetLoop} from '../hooks/use-get-loop'

interface RenameDialogProps {
  isOpen: boolean
  onClose: () => void
}

export function RenameDialog({isOpen, onClose}: RenameDialogProps) {
  const loopData = useLoopLens(l => ({title: l?.title, description: l?.description}))
  const {mutate: saveLoop} = useSaveLoop()
  const {getLoop} = useGetLoop()

  const [title, setTitle] = useState(loopData?.title || '')
  const [description, setDescription] = useState(loopData?.description || '')

  const handleTitleChange = (e: ChangeEvent<HTMLInputElement>) => {
    setTitle(e.target.value)
  }

  const handleDescriptionChange = (e: ChangeEvent<HTMLTextAreaElement>) => {
    setDescription(e.target.value)
  }

  const handleSave = () => {
    const loop = getLoop()
    if (!loop) return

    const titleChanged = title !== loop.title
    const descriptionChanged = description !== loop.description

    if (titleChanged || descriptionChanged) {
      const updatedLoop = {
        ...loop,
        title,
        description,
      }

      saveLoop(updatedLoop)
    }

    onClose()
  }

  const handleCancel = () => {
    onClose()
  }

  if (!isOpen || !loopData) return null

  return (
    <Dialog
      title="Rename Loop"
      onClose={handleCancel}
      footerButtons={[
        {
          content: 'Cancel',
          buttonType: 'normal',
          onClick: handleCancel,
        },
        {
          content: 'Save',
          buttonType: 'primary',
          onClick: handleSave,
        },
      ]}
    >
      <div className={styles.container}>
        <FormControl>
          <FormControl.Label>Name</FormControl.Label>
          <TextInput block value={title} onChange={handleTitleChange} placeholder="Loop name" />
          <FormControl.Caption>Memorable name that helps you find your loop.</FormControl.Caption>
        </FormControl>

        <FormControl>
          <FormControl.Label>Description</FormControl.Label>
          <div className={styles.descriptionInput}>
            <TextArea
              block
              value={description}
              onChange={handleDescriptionChange}
              rows={4}
              maxLength={200}
              resize="vertical"
              placeholder="Describe what this loop does"
            />
            <div className={styles.descriptionCounter}>
              <span>{description?.length ?? 0}</span> / 200
            </div>
          </div>
          <FormControl.Caption>
            Shows beneath the title on your loop overview page and does not impact responses.
          </FormControl.Caption>
        </FormControl>
      </div>
    </Dialog>
  )
}

try{ RenameDialog.displayName ||= 'RenameDialog' } catch {}