import {useMutation, useQueryClient} from '@github-ui/react-query'
import {useLoopsService} from '../../contexts/LoopsServiceProvider'
import type {Execution, NodeExecution} from '../../types/execution'
import {defaultNodeState} from '../../types/execution'
import {isNodeRunning} from '../../utils/execution-helpers'
import type {NodeValue} from '../../types/app'
import {useLoopID} from '../../state/lenses'
import {executionQueryKey, useExecutionVersion} from '../queries/use-execution'

function useUpdateExecutionMutation<TVariables = void>(
  updateFn: (execution: Execution, variables: TVariables) => Execution,
) {
  const queryClient = useQueryClient()
  const service = useLoopsService()
  const loopID = useLoopID()
  const version = useExecutionVersion()

  return useMutation({
    mutationFn: async (variables: TVariables) => {
      if (!loopID) throw new Error('No loop to execute.')
      if (!version) throw new Error('No version found.')

      const queryKey = executionQueryKey(loopID, version)
      const currentExecution = queryClient.getQueryData<Execution>(queryKey)
      if (!currentExecution) throw new Error('No current execution')

      const updatedState = updateFn(currentExecution, variables)
      return await service.updateExecution(loopID, version, currentExecution.id, updatedState)
    },
    onMutate: async (variables: TVariables) => {
      if (!loopID) throw new Error('No loop to execute.')
      if (!version) throw new Error('No version found.')

      const queryKey = executionQueryKey(loopID, version)

      // Snapshot the previous value
      const previousExecution = queryClient.getQueryData<Execution>(queryKey)

      if (previousExecution) {
        const optimisticState = updateFn(previousExecution, variables)
        queryClient.setQueryData(queryKey, optimisticState)
      }

      await queryClient.cancelQueries({queryKey}, {revert: false})
    },
  })
}

function useUpdateNodeExecutionMutation<TVariables extends {nodeID: string} = {nodeID: string}>(
  updateFn: (existingNodeExecution: NodeExecution | undefined, variables: TVariables) => NodeExecution,
) {
  const queryClient = useQueryClient()
  const service = useLoopsService()
  const loopID = useLoopID()
  const version = useExecutionVersion()

  return useMutation({
    mutationFn: async (variables: TVariables) => {
      if (!loopID) throw new Error('No loop to execute.')
      if (!version) throw new Error('No version found.')

      const queryKey = executionQueryKey(loopID, version)
      const currentExecution = queryClient.getQueryData<Execution>(queryKey)
      if (!currentExecution) throw new Error('No current execution')

      const {nodeID} = variables
      const existingNodeExecution = currentExecution.nodes[nodeID]
      const updatedNodeExecution = updateFn(existingNodeExecution, variables)

      return await service.updateNodeExecution(loopID, version, currentExecution.id, nodeID, updatedNodeExecution)
    },
    onMutate: async (variables: TVariables) => {
      if (!loopID) throw new Error('No loop to execute.')
      if (!version) throw new Error('No version found.')

      const queryKey = executionQueryKey(loopID, version)

      const previousExecution = queryClient.getQueryData<Execution>(queryKey)
      if (previousExecution) {
        const {nodeID} = variables
        const existingNodeExecution = previousExecution.nodes[nodeID]
        const updatedNodeExecution = updateFn(existingNodeExecution, variables)

        const optimisticState: Execution = {
          ...previousExecution,
          nodes: {
            ...previousExecution.nodes,
            [nodeID]: updatedNodeExecution,
          },
        }
        queryClient.setQueryData(queryKey, optimisticState)
      }

      await queryClient.cancelQueries({queryKey}, {revert: false})
    },
    onSuccess: (result, variables) => {
      if (!result.success || !loopID || !version) return

      const queryKey = executionQueryKey(loopID, version)

      queryClient.setQueryData<Execution>(queryKey, previousExecution => {
        if (!previousExecution) return previousExecution
        const {nodeID} = variables

        const previousNode = previousExecution.nodes[variables.nodeID]
        const updatedNode = result.data

        if (previousNode?.completedAt !== undefined && previousNode.completedAt > 0 && !updatedNode.completedAt) {
          // avoid race condition where "start node execution" success callback happens after
          // the "complete node execution" optimistic update
          return previousExecution
        }

        const updatedExecution: Execution = {
          ...previousExecution,
          nodes: {
            ...previousExecution.nodes,
            [nodeID]: updatedNode, // The actual updated execution
          },
        }

        return updatedExecution
      })
    },
  })
}

export function useUpdateNodeValueMutation() {
  return useUpdateNodeExecutionMutation<{nodeID: string; value: NodeValue}>((existingNodeExecution, {value}) => {
    // Extract resources if the value contains them (from GraphQL responses)
    let resources: Array<{type: string; id: string}> | undefined
    let actualValue = value
    if (value && typeof value === 'object' && 'data' in value && 'resources' in value) {
      const graphQLResult = value as {data: NodeValue; resources: Array<{type: string; id: string}>}
      resources = graphQLResult.resources
      actualValue = graphQLResult.data
    }

    return {
      ...(existingNodeExecution ?? defaultNodeState),
      value: actualValue,
      resources,
      completedAt: Date.now(),
    }
  })
}

export function useUpdateNodeErrorMutation() {
  return useUpdateNodeExecutionMutation<{nodeID: string; error: string}>((existingNodeExecution, {error}) => ({
    ...(existingNodeExecution ?? defaultNodeState),
    error,
    value: null,
    completedAt: Date.now(),
  }))
}

export function useSetRunningMutation() {
  return useUpdateNodeExecutionMutation<{nodeID: string}>(existingNodeExecution => ({
    ...(existingNodeExecution ?? defaultNodeState),
    startedAt: Date.now(),
    completedAt: undefined,
  }))
}

export function useCancelExecutionMutation() {
  return useUpdateExecutionMutation(execution => ({
    ...execution,
    nodes: Object.fromEntries(
      Object.entries(execution.nodes).map(([nodeId, nodeState]) => [
        nodeId,
        isNodeRunning(nodeState)
          ? {
              ...nodeState,
              completedAt: Date.now(),
            }
          : nodeState,
      ]),
    ),
  }))
}
