import type {Loop, Node} from '../types/app'

/**
 * Add a node to the pipeline
 */
export function addNodeToPipeline(pipeline: Loop, node: Node): Loop {
  if (!pipeline) return pipeline

  return {
    ...pipeline,
    nodes: [...(pipeline.nodes || []), node],
    updatedAt: Date.now(),
  }
}

/**
 * Remove a node from the pipeline
 */
export function removeNodeFromPipeline(pipeline: Loop, nodeId: string): Loop {
  if (!pipeline) return pipeline

  return {
    ...pipeline,
    nodes: pipeline.nodes.filter(n => n.id !== nodeId),
    updatedAt: Date.now(),
  }
}

/**
 * Update a node in the pipeline
 */
export function updateNodeInPipeline(pipeline: Loop, nodeId: string, updates: Partial<Node>): Loop {
  if (!pipeline) return pipeline

  const nodeIndex = pipeline.nodes.findIndex(n => n.id === nodeId)
  if (nodeIndex === -1) {
    // If the node doesn't exist, create a new one with the updates
    return addNodeToPipeline(pipeline, {
      id: nodeId,
      type: 'text',
      title: '',
      description: '',
      content: '',
      ...updates,
    } as Node)
  } else {
    const node = pipeline.nodes[nodeIndex]
    return {
      ...pipeline,
      nodes: [
        ...pipeline.nodes.slice(0, nodeIndex),
        {...node, ...updates} as Node,
        ...pipeline.nodes.slice(nodeIndex + 1),
      ],
      updatedAt: Date.now(),
    }
  }
}

/**
 * Update node content in a pipeline
 */
export function updateNodeContentInPipeline(pipeline: Loop, nodeId: string, content: string): Loop {
  if (!pipeline) return pipeline
  return updateNodeInPipeline(pipeline, nodeId, {content})
}
