import {DatePicker as PrimerDatePicker} from '@github-ui/date-picker'
import {useDebounce} from '@github-ui/use-debounce'
import {IconButton, FormControl} from '@primer/react'
import {CalendarIcon} from '@primer/octicons-react'
import styles from './DatePicker.module.css'
import {clsx} from 'clsx'
import type {ChangeEvent, HTMLAttributes} from 'react'
import {useEffect, useState} from 'react'
import {parseStringToDate, formatDateAsYYYYMMDD, isValidDateOrMacro} from '../../utils/dates'
import {TextInput} from './TextInput'

function getValidationState(value: string) {
  if (!value) return {isValid: true, parsedDate: null}
  const isValid = isValidDateOrMacro(value)
  const parsedDate = isValid ? parseStringToDate(value) : null
  return {isValid, parsedDate}
}

interface DatePickerProps {
  value: string
  onChange: (value: string) => void
  placeholder?: string
  className?: string
}

export function DatePicker({value, onChange, placeholder = 'Enter a date...', className}: DatePickerProps) {
  // Debounce the validation and date parsing functions
  const [validationState, setValidationState] = useState(() => getValidationState(value))

  const debouncedValidateAndParse = useDebounce((inputValue: string) => {
    const valid = getValidationState(inputValue)
    setValidationState(valid)
  }, 500)

  // Update validation state when value changes
  useEffect(() => {
    debouncedValidateAndParse(value)
  }, [value, debouncedValidateAndParse])

  const handleDatePickerChange = (date: Date | null) => {
    if (date) {
      const formattedDate = formatDateAsYYYYMMDD(date)
      onChange(formattedDate || '')
    } else {
      onChange('')
    }
  }

  const handleTextInputChange = (event: ChangeEvent<HTMLInputElement>) => {
    onChange(event.target.value)
  }

  const hasError = value && !validationState.isValid

  return (
    <div className={clsx(styles.dateContainer, className)}>
      <FormControl>
        <FormControl.Label visuallyHidden>Enter a date</FormControl.Label>
        <TextInput
          value={value}
          onChange={handleTextInputChange}
          placeholder={placeholder}
          trailingAction={
            <PrimerDatePicker
              value={validationState.parsedDate}
              onChange={handleDatePickerChange}
              anchor={(props: HTMLAttributes<HTMLElement>) => {
                // Extract and handle conflicting aria properties
                const {['aria-labelledby']: ariaLabelledBy, ...restProps} = props
                return (
                  <IconButton
                    {...restProps}
                    aria-label="Select date"
                    className={clsx(restProps.className, styles.datePickerButton)}
                    icon={CalendarIcon}
                    size="small"
                    variant="invisible"
                  />
                )
              }}
            />
          }
        />
        <FormControl.Caption className={styles.caption}>
          Choose a date or use @today with modifiers (d, w, m, y), for example @today-3d.
        </FormControl.Caption>
        {hasError && <FormControl.Validation variant="error">Invalid date or macro</FormControl.Validation>}
      </FormControl>
    </div>
  )
}

try{ DatePicker.displayName ||= 'DatePicker' } catch {}