import {useState, type ChangeEvent} from 'react'
import {usePreviousValue} from '@github-ui/use-previous-value'

export function useControlledInput<T extends HTMLInputElement | HTMLTextAreaElement>(
  controlledValue?: string,
  onChange?: (event: ChangeEvent<T>) => void,
) {
  const [internalValue, setInternalValue] = useState(controlledValue || '')
  const prevControlledValue = usePreviousValue(controlledValue)

  // Update internal state when controlled value changes externally
  if (controlledValue !== prevControlledValue && controlledValue !== internalValue) {
    setInternalValue(controlledValue || '')
  }

  const handleChange = (event: ChangeEvent<T>) => {
    const newValue = event.target.value
    setInternalValue(newValue)
    onChange?.(event)
  }

  return {
    value: internalValue,
    onChange: handleChange,
  }
}
