import {useLoopsDispatch, useLoopsStateLens} from '../contexts/LoopsStateProvider'

export type BannerType = 'duplicated' | 'linkCopied'

/**
 * Hook for managing one-time banners that show after certain actions.
 * Returns the current visibility state and a function to show the banner.
 */
export function useOneTimeBanner(type: BannerType) {
  const dispatch = useLoopsDispatch()

  const isVisible = useLoopsStateLens(state => {
    switch (type) {
      case 'duplicated':
        return state.showDuplicatedBanner
      case 'linkCopied':
        return state.showLinkCopiedBanner
      default:
        return false
    }
  })

  const showBanner = () => {
    switch (type) {
      case 'duplicated':
        dispatch({type: 'SHOW_DUPLICATED_BANNER'})
        break
      case 'linkCopied':
        dispatch({type: 'SHOW_LINK_COPIED_BANNER'})
        break
    }
  }

  const hideBanner = () => {
    switch (type) {
      case 'duplicated':
        dispatch({type: 'HIDE_DUPLICATED_BANNER'})
        break
      case 'linkCopied':
        dispatch({type: 'HIDE_LINK_COPIED_BANNER'})
        break
    }
  }

  return {
    isVisible,
    showBanner,
    hideBanner,
  }
}
