import {
  useUpdateNodeValueMutation,
  useUpdateNodeErrorMutation,
  useSetRunningMutation,
} from './mutations/use-execution-mutations'
import type {LoopRunnerAction} from '../service/loop-runner'
import {useQueryClient} from '@github-ui/react-query'
import type {Execution} from '../types/execution'
import {defaultNodeState} from '../types/execution'
import {useExecutionQueryKey} from './queries/use-execution'

/**
 * Shared hook that creates a progress handler for pipeline execution.
 * Converts PipelineRunnerAction to mutations for updating execution state.
 */
export function useProgressHandler() {
  const {mutate: updateNodeValue} = useUpdateNodeValueMutation()
  const {mutate: updateNodeError} = useUpdateNodeErrorMutation()
  const {mutate: setRunning} = useSetRunningMutation()
  const queryClient = useQueryClient()
  const queryKey = useExecutionQueryKey()

  const createProgressHandler = () => (action: LoopRunnerAction) => {
    if (!queryKey) return
    switch (action.type) {
      case 'UPDATE_NODE_VALUE':
        updateNodeValue({
          nodeID: action.nodeID,
          value: action.value,
        })
        break
      case 'UPDATE_NODE_VALUE_PARTIAL': {
        // don't write partial values to the server, just optimistically update the local state
        const previousExecution = queryClient.getQueryData<Execution>(queryKey)
        if (previousExecution) {
          const optimisticState: Execution = {
            ...previousExecution,
            nodes: {
              ...previousExecution.nodes,
              [action.nodeID]: {
                ...(previousExecution.nodes[action.nodeID] ?? defaultNodeState),
                value: action.value,
              },
            },
          }
          queryClient.setQueryData(queryKey, optimisticState)
        }
        break
      }
      case 'UPDATE_NODE_ERROR':
        updateNodeError({
          nodeID: action.nodeID,
          error: action.error,
        })
        break
      case 'SET_RUNNING':
        setRunning({
          nodeID: action.nodeID,
        })
        break
      default:
        break
    }
  }

  return {createProgressHandler}
}
