import type {CopilotChatReference} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {useLoopsDispatch} from '../contexts/LoopsStateProvider'
import {parseUIStateFromURL} from '../utils/url-sync'
import type {MouseEvent} from 'react'
import {useGetLoop} from './use-get-loop'

export function useSelectReference() {
  const dispatch = useLoopsDispatch()
  const {getLoop} = useGetLoop()

  return (reference: CopilotChatReference, event?: MouseEvent<HTMLAnchorElement>) => {
    // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
    if (event?.metaKey || event?.ctrlKey) {
      event?.preventDefault()
      return
    }

    if (reference.type === 'loop-node' && reference.url) {
      event?.preventDefault()

      const url = new URL(reference.url, window.location.origin)
      const searchParams = new URLSearchParams(url.search)
      const urlState = parseUIStateFromURL(searchParams)

      const loop = getLoop()
      if (!loop?.nodes.some(node => node.id === urlState.focusedNodeId)) {
        return
      }

      dispatch({type: 'SET_STATE', state: urlState})
    }
  }
}
