import {ChatMessage} from '@github-ui/copilot-chat/components/ChatMessage'
import {ChatMessagesGroup} from '@github-ui/copilot-chat/components/ChatMessagesGroup'
import {LegalDisclaimer} from '@github-ui/copilot-chat/components/LegalDisclaimer'
import {useChatState} from '@github-ui/copilot-chat/CopilotChatContext'
import {useGroupedMessages} from '@github-ui/copilot-chat/hooks/use-grouped-messages'
import {NullMessageId} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import type {CopilotChatMessage} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import type {RefObject} from 'react'
import {AutofixChatMessage} from './AutofixChatMessage'
import styles from './ChatMessages.module.css'
import {isAutofixMessage} from '../../utils/loop-error-messages'
import {useChatScroll} from '@github-ui/copilot-chat/components/ChatScrollContainer'
import {useLayoutEffect} from '@github-ui/use-layout-effect'
import {useSelectReference} from '../../hooks/use-select-reference'

interface ChatMessagesProps {
  inputRef: RefObject<HTMLTextAreaElement>
}

const isMessageEmpty = (message: CopilotChatMessage) => {
  return (
    !message.content &&
    (!message.confirmations || message.confirmations.length === 0) &&
    (!message.clientConfirmations || message.clientConfirmations.length === 0)
  )
}

export function ChatMessages({inputRef}: ChatMessagesProps) {
  const state = useChatState()
  const {isWaitingOnCopilot, streamingMessage} = state

  const {scrollToBottom} = useChatScroll()

  // Instant scroll to bottom on mount
  useLayoutEffect(() => scrollToBottom('instant'), [scrollToBottom])

  const {messages: activeMessages, groupedMessages} = useGroupedMessages(state)
  const selectReference = useSelectReference()

  return (
    <div className={styles.messagesWrapper}>
      <div className={styles.messagesContainer}>
        {activeMessages.length === 0 && (
          <div className={styles.legalDisclaimerWrapper}>
            <p className={styles.legalDisclaimer}>
              <LegalDisclaimer />
            </p>
          </div>
        )}
        {groupedMessages.map((group, i) => {
          if (group.length === 0 || !group[0]) return null

          const groupKey = `group-${group[0].id}`
          return (
            <ChatMessagesGroup key={groupKey} isLastGroup={i === groupedMessages.length - 1}>
              {group.map((message, j) => {
                const isLatestMessage = i === groupedMessages.length - 1 && j === group.length - 1
                const shouldShowMessage =
                  message === streamingMessage ||
                  message.id === NullMessageId ||
                  !isMessageEmpty(message) ||
                  message.error

                if (!shouldShowMessage) return null

                const isAutofix = message.role === 'user' && isAutofixMessage(message.content)
                if (isAutofix) {
                  // Autofix messages show as "running" when it or it's response is the latest message and streaming
                  const lastMessageInGroup = group[group.length - 1]
                  const isResponseLatestMessage = i === groupedMessages.length - 1
                  const isRunning = isLatestMessage && isWaitingOnCopilot
                  const isResponseRunning =
                    lastMessageInGroup?.role === 'assistant' &&
                    (lastMessageInGroup === streamingMessage ||
                      (lastMessageInGroup && isResponseLatestMessage && isWaitingOnCopilot))

                  return <AutofixChatMessage key={message.id} isRunning={isRunning || isResponseRunning} />
                }

                return (
                  <ChatMessage
                    key={message.id}
                    isLatestMessage={isLatestMessage}
                    isFirstReply={activeMessages.length === 1}
                    isStreaming={message.id === streamingMessage?.id || (isLatestMessage && isWaitingOnCopilot)}
                    message={message}
                    inputRef={inputRef}
                    onClickReference={selectReference}
                  />
                )
              })}
            </ChatMessagesGroup>
          )
        })}
      </div>
    </div>
  )
}

try{ ChatMessages.displayName ||= 'ChatMessages' } catch {}