export const generateRoundedVerticalPath = (points: Array<[number, number]>): string => {
  if (points.length < 2) return ''

  const [startX, startY] = points[0] || [0, 0]
  const lastPoint = points[points.length - 1]
  const [endX, endY] = lastPoint ? lastPoint : [0, 0]

  const deltaX = endX - startX
  const absDeltaX = Math.abs(deltaX)
  const isStraight = absDeltaX < 1
  if (isStraight) return `M ${startX},${startY} L ${endX},${endY}`

  const baseCornerRadius = 12
  let cornerRadius = baseCornerRadius

  // If the horizontal distance is too small to fit two full radius arcs and a segment,
  // reduce the radius proportionally. If still too small, fallback to straight.
  if (absDeltaX < baseCornerRadius * 2) {
    cornerRadius = Math.max(1, absDeltaX / 2 - 1)
  }
  const verticalSplit = (startY + endY) / 2

  const verticalDown = verticalSplit - cornerRadius
  const verticalUp = verticalSplit + cornerRadius

  const directionX = deltaX > 0 ? 1 : -1
  const horizontalLength = Math.max(0, absDeltaX - cornerRadius * 2)

  return `
    M ${startX},${startY}
    L ${startX},${verticalDown}
    A ${cornerRadius},${cornerRadius} 0 0 ${directionX > 0 ? 0 : 1} ${
      startX + directionX * cornerRadius
    },${verticalSplit}
    L ${startX + directionX * (cornerRadius + horizontalLength)},${verticalSplit}
    A ${cornerRadius},${cornerRadius} 0 0 ${directionX > 0 ? 1 : 0} ${endX},${verticalUp}
    L ${endX},${endY}
  `
    .trim()
    .replace(/\s+/g, ' ')
}
