import {useLoopsStateLens} from '../contexts/LoopsStateProvider'
import {draftVersion, latestVersion as latestVersionKeyword} from '../utils/versions'
import {useLoopVersions} from './queries/use-loop-versions'

/**
 * Resolve the selected version of the loop to a specific version string.
 *
 * @returns An object containing:
 * - `selectedVersion`: The resolved version string (e.g. 0.0.1 instead of just "latest")
 * - `isLatest`: A boolean indicating if the resolved version is the latest version.
 */
export function useSelectedVersion(): {
  selectedVersion: string | null
  isLatest: boolean
} {
  const {data: latestVersion} = useLoopVersions(versions => {
    if (!versions || versions.length === 0) return null
    const sortedVersions = versions
      .sort((a, b) => a.updatedAt - b.updatedAt)
      .filter(version => version.version !== draftVersion)
    return sortedVersions[sortedVersions.length - 1]?.version
  })
  const selectedVersion = useLoopsStateLens(state => state.version)

  if (selectedVersion === latestVersionKeyword || selectedVersion === draftVersion) {
    return {selectedVersion: latestVersion ?? null, isLatest: true}
  }

  return {selectedVersion, isLatest: selectedVersion === latestVersion}
}
