import type {ReactNode} from 'react'
import {CopyToClipboardButton} from '@github-ui/copy-to-clipboard/Button'
import {CopyIcon} from '@primer/octicons-react'
import styles from './InputSection.module.css'
import {clsx} from 'clsx'

interface InputSectionLayoutProps {
  additionalFields?: ReactNode
  content: string | null | undefined
  contentEditor: ReactNode
  children?: ReactNode
  inputLabelId?: string
}

export function InputSectionLayout({
  additionalFields,
  content,
  contentEditor,
  children,
  inputLabelId,
}: InputSectionLayoutProps) {
  return (
    <div className={styles.container}>
      {additionalFields}
      <div className={styles.nodeInput}>
        <div className={styles.header}>
          <span id={inputLabelId} className={clsx(styles.groupTitle)}>
            Input
          </span>
          <CopyToClipboardButton
            icon={CopyIcon}
            variant="invisible"
            ariaLabel="Copy input"
            textToCopy={content ? content.toString() : ''}
          />
        </div>
        <>
          {contentEditor}
          {children}
        </>
      </div>
    </div>
  )
}

try{ InputSectionLayout.displayName ||= 'InputSectionLayout' } catch {}