import {Button, Stack, Link} from '@primer/react'
import styles from './ReadonlyAboutPanel.module.css'
import {useDuplicateLoop} from '../hooks/use-duplicate-loop'
import {useLoopLens} from '../hooks/use-loop-lens'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {useIsReadonly} from '../hooks/use-is-readonly'

export function ReadonlyAboutPanel() {
  const {isReadonly, reason} = useIsReadonly()
  const duplicateSharedLoop = useDuplicateLoop()

  const title = useLoopLens(loop => loop?.title)
  const description = useLoopLens(loop => loop?.description)
  const ownerLogin = useLoopLens(loop => loop?.ownerLogin)

  if (!isReadonly || reason !== 'shared') {
    return null
  }

  return (
    <div className={styles.container}>
      <Stack className={styles.readonlySection}>
        {ownerLogin && (
          <div className={styles.readonlyIconView}>
            <GitHubAvatar src={`/${ownerLogin}.png`} size={48} />
          </div>
        )}
        <Stack className={styles.readonlyContent}>
          <h2 className={styles.readonlyTitle}>{title}</h2>
          {description && <p className={styles.readonlyDescription}>{description}</p>}
          <Button
            variant="default"
            size="small"
            onClick={duplicateSharedLoop}
            className={styles.readonlyDuplicateButton}
          >
            Duplicate
          </Button>
          {ownerLogin && (
            <p className={styles.readonlyDescription}>
              Created by{' '}
              <Link href={`/${ownerLogin}`} inline>
                {ownerLogin}
              </Link>
            </p>
          )}
        </Stack>
      </Stack>
    </div>
  )
}

try{ ReadonlyAboutPanel.displayName ||= 'ReadonlyAboutPanel' } catch {}