import {Button, Stack, FormControl} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {useEffect, useState} from 'react'
import {NodeInput} from '../nodes/NodeInput'
import styles from './InputPickerPanel.module.css'
import {useLoopLens} from '../../hooks/use-loop-lens'
import {getInputNodes} from '../../utils/input-detection'

export interface InputPickerPanelProps {
  isOpen: boolean
  onClose: () => void
  onRun: (values: Record<string, string>) => void
}

export function InputPickerPanel({isOpen, onClose, onRun}: InputPickerPanelProps) {
  const inputNodes = useLoopLens(loop => (loop ? getInputNodes(loop) : []))

  const [currentValues, setCurrentValues] = useState<Record<string, string>>({})

  // Initialize with node content when opening
  useEffect(() => {
    if (isOpen) {
      const initialValues: Record<string, string> = {}
      for (const node of inputNodes) {
        initialValues[node.id] = node.content || ''
      }
      setCurrentValues(initialValues)
    }
  }, [isOpen, inputNodes])

  const handleValueChange = (nodeId: string, value: string) => {
    setCurrentValues(prev => ({
      ...prev,
      [nodeId]: value,
    }))
  }

  const handleRun = () => {
    onRun(currentValues)
    onClose()
  }

  if (!isOpen) {
    return null
  }

  return (
    <Dialog title="Customize Input Values" position="right" onClose={onClose}>
      <Stack direction="vertical" gap="normal">
        <p className={styles.description}>Modify the input values below before running the loop:</p>

        {inputNodes.map(node => {
          const nodeId = node.id
          const currentValue = currentValues[nodeId] || ''

          return (
            <FormControl key={nodeId}>
              <FormControl.Label>{node.title || `Input ${nodeId}`}</FormControl.Label>
              <NodeInput
                content={currentValue}
                nodeId={nodeId}
                onChange={value => handleValueChange(nodeId, value)}
                inputLabelId={`input-label-${nodeId}`}
                compact
              />
            </FormControl>
          )
        })}

        <Stack direction="horizontal" gap="condensed" justify="end">
          <Button type="button" onClick={onClose}>
            Cancel
          </Button>
          <Button type="button" variant="primary" onClick={handleRun}>
            Run
          </Button>
        </Stack>
      </Stack>
    </Dialog>
  )
}

try{ InputPickerPanel.displayName ||= 'InputPickerPanel' } catch {}