import {ExecuteButton} from './ExecuteButton'
import {InputPickerPanel} from '../modals/InputPickerPanel'
import {useExecuteButton} from '../../hooks/use-execute-button'

export function ExecuteButtonWithModal() {
  const {
    handleInputPickerClose,
    handleInputPickerRun,
    handleRunButtonClick,
    handleRunWithInputs,
    handleStopButtonClick,
    pipelineRunning,
    hasInputNodes,
    showInputPicker,
  } = useExecuteButton()

  return (
    <>
      <ExecuteButton
        isLoading={pipelineRunning}
        onClick={handleRunButtonClick}
        onStop={handleStopButtonClick}
        variant="primary"
        showPickInputsOption={hasInputNodes}
        onRunWithInputs={handleRunWithInputs}
      />
      <InputPickerPanel isOpen={showInputPicker} onClose={handleInputPickerClose} onRun={handleInputPickerRun} />
    </>
  )
}

try{ ExecuteButtonWithModal.displayName ||= 'ExecuteButtonWithModal' } catch {}