import {Spinner} from '@primer/react'
import {CheckIcon} from '@primer/octicons-react'
import styles from './AutofixChatMessage.module.css'

interface AutofixChatMessageProps {
  isRunning: boolean
}

export function AutofixChatMessage({isRunning}: AutofixChatMessageProps) {
  return (
    <div className={styles.container}>
      {isRunning ? <Spinner size="small" /> : <CheckIcon size={16} className={styles.icon} />}
      <span className={styles.text}>Copilot found an issue in your loop. Fixing now...</span>
    </div>
  )
}

try{ AutofixChatMessage.displayName ||= 'AutofixChatMessage' } catch {}