import {useLoopLens} from '../hooks/use-loop-lens'
import {useValidationErrors} from '../hooks/use-validation-errors'
import {useExecution} from '../hooks/queries/use-execution'
import type {Loop, LoopValidationError, Node, NodeValue} from '../types/app'
import type {Execution} from '../types/execution'
import {getInputIds, getOutputNodes, isVirtualOutputNode} from '../utils/loops'
import {isExecutionRunning, isNodeRunning} from '../utils/execution-helpers'
import {useLoop} from '../hooks/queries/use-loop'

/**
 * The edge component uses internal state lenses to determine the edge's status (`IDLE`, `PROCESSING`, `COMPLETED`, or `ERROR`).
 * The visual representation of the edge changes based on this status.
 */
export type Status = 'IDLE' | 'PROCESSING' | 'COMPLETED' | 'ERROR'

export const nodeDefinition = (nodeID: string, pipeline: Loop | null | undefined) => {
  return pipeline?.nodes.find(n => n.id === nodeID)
}

export function useNodeContent(nodeId: string) {
  return useLoopLens(loop => nodeDefinition(nodeId, loop)?.content ?? '')
}

export function useNodeType(nodeId: string) {
  return useLoopLens(loop => nodeDefinition(nodeId, loop)?.type ?? 'text')
}

export function useNodeInputIds(nodeId: string): string[] {
  const joined = useLoopLens(loop => {
    // Return a string so that we only re-render when the actual inputs have changed
    const node = nodeDefinition(nodeId, loop)
    if (!node) return ''
    return [...getInputIds(node)].sort().join('|')
  })
  return joined === '' ? [] : joined.split('|')
}

export function useNode(nodeID: string): Node | undefined {
  return useLoopLens(loop => nodeDefinition(nodeID, loop))
}

export function useNodeValue(nodeID: string): NodeValue {
  const {data: nodeValue} = useExecution(executionState => executionState?.nodes[nodeID]?.value ?? null)
  return nodeValue ?? null
}

export function useNodeError(nodeID: string): string | undefined {
  const {data: nodeError} = useExecution(executionState => executionState?.nodes[nodeID]?.error)
  return nodeError
}

export function useNodeRunning(nodeID: string): boolean {
  const {data: running} = useExecution(executionState => isNodeRunning(executionState?.nodes[nodeID]))
  return running ?? false
}

export function useLoopIsRunning(): boolean {
  const {data: running} = useExecution(isExecutionRunning)
  return running ?? false
}

/**
 * Helper function to determine the status of a single node
 */
function getNodeStatus(
  nodeId: string,
  executionState: Execution | null | undefined,
  validationErrors: LoopValidationError[],
): Status {
  if (!nodeId || !executionState) return 'IDLE'

  const nodeState = executionState.nodes[nodeId]
  const nodeIsRunning = isNodeRunning(nodeState)
  const hasValue = !!nodeState?.value
  const hasError = !!nodeState?.error
  const hasValidationError = validationErrors.some(e => e.involvedNodes.includes(nodeId))

  if (hasError || hasValidationError) return 'ERROR'
  if (nodeIsRunning) return 'PROCESSING'
  if (hasValue) return 'COMPLETED'
  return 'IDLE'
}

export function useNodeIndicatorStatus(nodeId: string): Status {
  const validationErrors = useValidationErrors()
  const {data: statusKey} = useExecution(executionState => getNodeStatus(nodeId, executionState, validationErrors))

  return (statusKey?.toUpperCase() ?? 'IDLE') as Status
}

export function useVirtualNodeIndicatorStatus(): Status {
  const validationErrors = useValidationErrors()
  const {data: currentLoop} = useLoop()

  const {data: statusKey} = useExecution(executionState => {
    if (!executionState || !currentLoop) return 'IDLE'
    const outputNodes = getOutputNodes(currentLoop)

    if (outputNodes.length === 0) return 'IDLE'

    // Check the status of each output node
    const outputStatuses: Status[] = outputNodes.map(outputNode =>
      getNodeStatus(outputNode.id, executionState, validationErrors),
    )
    // Apply the priority logic
    if (outputStatuses.some(status => status === 'ERROR')) {
      return 'ERROR'
    }
    if (outputStatuses.some(status => status === 'PROCESSING')) {
      return 'PROCESSING'
    }
    if (outputStatuses.every(status => status === 'COMPLETED')) {
      return 'COMPLETED'
    }
    return 'IDLE'
  })

  return (statusKey?.toUpperCase() ?? 'IDLE') as Status
}

export function useEdgeStatus(sourceNodeId: string, targetNodeId: string): Status {
  const validationErrors = useValidationErrors()
  const {data: statusKey} = useExecution(executionState => {
    if (!sourceNodeId || !targetNodeId || !executionState) return 'IDLE'

    const sourceNode = executionState.nodes[sourceNodeId]
    const targetNode = executionState.nodes[targetNodeId]

    const targetIsRunning = isNodeRunning(targetNode)
    const sourceHasValue = !!sourceNode?.value
    const targetHasValue = !!targetNode?.value || (isVirtualOutputNode(targetNodeId) && sourceHasValue)
    const sourceIsRunning = isNodeRunning(sourceNode)
    const sourceHasError = !!sourceNode?.error
    const sourceHasValidationError = validationErrors.some(e => e.involvedNodes.includes(sourceNodeId))

    if (sourceHasError || sourceHasValidationError) return 'ERROR'
    if (targetIsRunning) return 'PROCESSING'
    if (targetHasValue && sourceHasValue && !sourceIsRunning) return 'COMPLETED'
    return 'IDLE'
  })

  return (statusKey?.toUpperCase() ?? 'IDLE') as Status
}

export function useLoopID(): string | undefined {
  return useLoopLens(loop => loop?.id)
}
