import {KebabHorizontalIcon, TrashIcon, CommentIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, IconButton} from '@primer/react'
import {useLoopOperations} from '../../hooks/use-loop-operations'
import {isPostStaffShipFeaturesEnabled} from '../../utils/feature-flags'
import {useAddLoopNodeReference} from '../../hooks/use-add-loop-node-reference'
import {useLoopLens} from '../../hooks/use-loop-lens'
import {nodeDefinition} from '../../state/lenses'
import {sendEvent} from '@github-ui/hydro-analytics'

export function NodeContextMenu({nodeId}: {nodeId: string}) {
  const {removeNode} = useLoopOperations()
  const {toggleLoopNodeReference, isNodeReferenced} = useAddLoopNodeReference()
  const nodeTitle = useLoopLens(loop => nodeDefinition(nodeId, loop)?.title)
  const isReferenced = nodeTitle ? isNodeReferenced(nodeId, nodeTitle) : false

  const handleDeleteNode = () => {
    removeNode(nodeId)
  }

  const handleReferenceInChat = () => {
    if (!nodeTitle) return

    // Send analytics event for context menu click
    sendEvent('dotcom_chat.activate', {
      target: 'LOOP_NODE_REFERENCE_CONTEXT_MENU',
      mode: 'loops',
    })

    toggleLoopNodeReference(nodeId, nodeTitle, 'nodeContextMenu')
  }

  if (!isPostStaffShipFeaturesEnabled()) return null

  return (
    <ActionMenu>
      <ActionMenu.Anchor>
        <IconButton aria-label="Additional actions" icon={KebabHorizontalIcon} />
      </ActionMenu.Anchor>
      <ActionMenu.Overlay align="end">
        <ActionList>
          <ActionList.Item onSelect={handleReferenceInChat}>
            <ActionList.LeadingVisual>
              <CommentIcon />
            </ActionList.LeadingVisual>
            <span>{isReferenced ? 'Remove from Chat' : 'Reference in Chat'}</span>
          </ActionList.Item>
          <ActionList.Item onSelect={handleDeleteNode} variant="danger">
            <ActionList.LeadingVisual>
              <TrashIcon />
            </ActionList.LeadingVisual>
            Delete
          </ActionList.Item>
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}

try{ NodeContextMenu.displayName ||= 'NodeContextMenu' } catch {}