import {lazy, Suspense, type CSSProperties} from 'react'
import {getQueryClient} from '@github-ui/react-core/query-client'

const ReactQueryDevtoolsPanel = lazy(async () => {
  // eslint-disable-next-line import/extensions
  const mod = await import('@tanstack/react-query-devtools/build/modern/production.js')
  return {default: mod.ReactQueryDevtoolsPanel}
})

interface DevtoolsPanelProps {
  onClose?: () => void
  style?: CSSProperties
}

export function AsyncReactQueryDevtoolsPanel({onClose, style}: DevtoolsPanelProps) {
  return (
    <Suspense fallback={null}>
      <ReactQueryDevtoolsPanel client={getQueryClient()} onClose={onClose} style={style} />
    </Suspense>
  )
}

try{ ReactQueryDevtoolsPanel.displayName ||= 'ReactQueryDevtoolsPanel' } catch {}
try{ AsyncReactQueryDevtoolsPanel.displayName ||= 'AsyncReactQueryDevtoolsPanel' } catch {}