import {useState} from 'react'
import {IconButton} from '@primer/react'
import {ToolsIcon, XIcon} from '@primer/octicons-react'
import {isStaff} from '@github-ui/stats'
import {AsyncReactQueryDevtoolsPanel} from './AsyncReactQueryDevtoolsPanel'
import styles from './LoopsDevtools.module.css'
import {isFeatureEnabled} from '@github-ui/feature-flags'

export function LoopsDevtools() {
  const [isOpen, setIsOpen] = useState(false)

  const handleToggle = () => setIsOpen(prev => !prev)

  const handleClose = () => setIsOpen(false)

  if (!isStaff() || !isFeatureEnabled('loops_react_query_devtools')) {
    return null
  }

  return (
    <>
      <div className={styles.toggleButton}>
        <IconButton
          icon={ToolsIcon}
          aria-label={isOpen ? 'Close React Query devtools' : 'Open React Query devtools'}
          onClick={handleToggle}
          variant="default"
        />
      </div>

      {isOpen && (
        <div className={styles.devtoolsContainer}>
          <div className={styles.header}>
            <span className={styles.title}>React Query Devtools</span>
            <IconButton
              icon={XIcon}
              aria-label="Close devtools"
              onClick={handleClose}
              variant="invisible"
              size="small"
            />
          </div>
          <div className={styles.content}>
            <AsyncReactQueryDevtoolsPanel onClose={handleClose} />
          </div>
        </div>
      )}
    </>
  )
}

try{ LoopsDevtools.displayName ||= 'LoopsDevtools' } catch {}