import {Banner} from '@primer/react/experimental'
import {Button} from '@primer/react'
import {sendEvent} from '@github-ui/hydro-analytics'
import {useDuplicateLoop} from '../../hooks/use-duplicate-loop'

export function DuplicateLoopBanner() {
  const duplicateSharedLoop = useDuplicateLoop()

  const handleDuplicate = () => {
    duplicateSharedLoop()
    sendEvent('node_action.select', {target: 'SHARED_LOOP_DUPLICATE', mode: 'loops'})
  }

  return (
    <Banner
      variant="info"
      title="Duplicate loop banner"
      hideTitle
      description="To edit a shared loop you need to duplicate it first."
      primaryAction={
        <Button onClick={handleDuplicate} size="small">
          Duplicate
        </Button>
      }
    />
  )
}

try{ DuplicateLoopBanner.displayName ||= 'DuplicateLoopBanner' } catch {}