import {ActionList, RelativeTime} from '@primer/react'
import {useLoopVersions} from '../../hooks/queries/use-loop-versions'
import {useLoopsDispatch} from '../../contexts/LoopsStateProvider'
import {useSelectedVersion} from '../../hooks/use-selected-version'
import {draftVersion} from '../../utils/versions'
import {useRef, useEffect} from 'react'

/**
 * Pure list of versions can be used in both in the desktop `VersionSelector` and inside the mobile header menu.
 */
export function VersionList({onAfterSelect}: {onAfterSelect?: () => void}) {
  const {data: versions, isLoading} = useLoopVersions()
  const dispatch = useLoopsDispatch()
  const {selectedVersion} = useSelectedVersion()
  const selectedItemRef = useRef<HTMLLIElement>(null)

  const sortedVersions = versions?.sort((a, b) => a.updatedAt - b.updatedAt).filter(v => v.version !== draftVersion)

  useEffect(() => {
    if (!selectedItemRef.current) return
    selectedItemRef.current.scrollIntoView({behavior: 'instant', block: 'nearest'})
  }, [sortedVersions?.length])

  if (!isLoading && (!sortedVersions || sortedVersions.length === 0)) return null

  const handleVersionSelected = (version: string) => {
    const mostRecentVersion = sortedVersions?.[sortedVersions.length - 1]?.version
    const versionToSet = version === mostRecentVersion ? draftVersion : version
    dispatch({type: 'SET_VERSION', version: versionToSet})
    onAfterSelect?.()
  }

  return (
    <ActionList selectionVariant="single" data-testid="version-list">
      {sortedVersions?.map(v => (
        <ActionList.Item
          key={v.id}
          ref={selectedVersion === v.version ? selectedItemRef : null}
          onSelect={() => handleVersionSelected(v.version)}
          selected={selectedVersion === v.version}
        >
          Version {v.version}
          <ActionList.Description variant="block">
            <RelativeTime date={new Date(v.updatedAt)} />
          </ActionList.Description>
        </ActionList.Item>
      ))}
    </ActionList>
  )
}

export default VersionList

try{ VersionList.displayName ||= 'VersionList' } catch {}