import type {NodeValue} from './app'

export interface Execution {
  loopID: string
  loopVersion: string
  createdAt: number
  nodes: Record<string, NodeExecution>
  id: string
  inputValues?: Record<string, string>
}

export interface NodeExecution {
  value?: NodeValue
  error?: string
  startedAt?: number
  completedAt?: number
  resources?: Array<{type: string; id: string}>
}

export const defaultNodeState: NodeExecution = {
  value: null,
  startedAt: undefined,
  completedAt: undefined,
}
