import {HeaderActions} from './controls/HeaderActions'
import {ViewToggle} from './controls/ViewToggle'
import {useNavigate} from '@github-ui/react-router'
import {Breadcrumbs} from '@github-ui/pacer/Breadcrumbs'
import {LoopBreadcrumbItem} from './controls/LoopBreadcrumbItem'
import {RenameDialog} from './RenameDialog'
import styles from './Header.module.css'
import {LOOPS_PATH} from '../utils/constants'
import {sendEvent} from '@github-ui/hydro-analytics'
import {useDuplicateLoop} from '../hooks/use-duplicate-loop'
import {createShareUrl} from '../utils/share'
import {useLoopDraftStatus} from '../hooks/use-loop-draft-status'
import {useState} from 'react'
import {useLoopLens} from '../hooks/use-loop-lens'
import {useLoopID} from '../state/lenses'
import {useGetLoop} from '../hooks/use-get-loop'
import {VersionSelector} from './controls/VersionSelector'
import {useSaveLoop} from '../hooks/mutations/use-save-loop'
import {useLayoutContext} from '@github-ui/pacer/Layout/layout-context'
import {LoopShareButton} from './LoopShareButton'
import {copilotFeatureFlags} from '@github-ui/copilot-chat/utils/copilot-feature-flags'
import {MobileHeaderMenu} from './controls/MobileHeaderMenu'

export function LeftHeader() {
  const loopTitle = useLoopLens(loop => loop?.title, 'latest')
  const loopID = useLoopID()
  const {hasChanges} = useLoopDraftStatus()
  const {mutate: saveLoop} = useSaveLoop()
  const [showRenameDialog, setShowRenameDialog] = useState(false)
  const {layoutBreakpoint: isMobile} = useLayoutContext()
  const {getLoop} = useGetLoop()
  const navigate = useNavigate()
  const duplicateLoop = useDuplicateLoop()

  const handleDeleteLoop = () => {
    navigate(LOOPS_PATH)
  }

  const copyLoopToClipboard = () => {
    const draftLoop = getLoop()
    if (!draftLoop) return

    const fieldsToCopy = {
      title: draftLoop.title,
      description: draftLoop.description,
      nodes: draftLoop.nodes,
    }

    const pipelineJson = JSON.stringify(fieldsToCopy, null, 2)
    navigator.clipboard.writeText(pipelineJson)
    sendEvent('dotcom_chat.activate', {target: 'HEADER_JSON_COPY', mode: 'loops'})
  }

  const shareLoop = () => {
    const draftLoop = getLoop()
    if (!draftLoop) return

    const shareUrl = createShareUrl(draftLoop)

    navigator.clipboard.writeText(shareUrl)
    sendEvent('dotcom_chat.activate', {target: 'LOOP_SHARE', mode: 'loops'})
  }

  const handleLoopsNavigation = () => {
    // With versioning enabled, auto-save on navigation if there are changes
    if (loopID && hasChanges) {
      saveLoop(loopID)
    }
    sendEvent('dotcom_chat.activate', {target: 'HEADER_WORKBENCH_CLOSE', mode: 'loops'})
  }

  const handleRenameLoop = () => {
    setShowRenameDialog(true)
  }

  return (
    <>
      <Breadcrumbs>
        <Breadcrumbs.Item href={LOOPS_PATH} onClick={handleLoopsNavigation}>
          Loops
        </Breadcrumbs.Item>
        <LoopBreadcrumbItem
          loopTitle={loopTitle || 'Untitled Loop'}
          loopId={loopID}
          onDelete={handleDeleteLoop}
          onCopyLoop={copyLoopToClipboard}
          onDuplicate={duplicateLoop}
          onShare={!copilotFeatureFlags.loopsShareButton ? shareLoop : undefined}
          onRename={handleRenameLoop}
        />
      </Breadcrumbs>
      {!isMobile && <VersionSelector />}
      <RenameDialog
        key={showRenameDialog.toString()}
        isOpen={showRenameDialog}
        onClose={() => setShowRenameDialog(false)}
      />
    </>
  )
}

export function RightHeader() {
  const {layoutBreakpoint: isMobile} = useLayoutContext()

  return (
    <div className={styles.right}>
      {isMobile ? (
        <MobileHeaderMenu />
      ) : (
        <>
          <ViewToggle />
          <div className={styles.actions}>
            <LoopShareButton />
            <HeaderActions />
          </div>
        </>
      )}
    </div>
  )
}

try{ LeftHeader.displayName ||= 'LeftHeader' } catch {}
try{ RightHeader.displayName ||= 'RightHeader' } catch {}