import type {LoopValidationError} from '../types/app'

export const VALIDATION_ERROR_MESSAGE_START = 'The following errors were found in the Loop configuration:'
export const RUNTIME_ERROR_MESSAGE_START = 'The following errors were found while running the Loop:'

export interface RuntimeError {
  nodeId: string
  error?: string
}

/**
 * Creates a formatted message for validation errors in the loop configuration.
 */
export function createValidationErrorMessage(validationErrors: LoopValidationError[]): string {
  const errorList = validationErrors.map(formatValidationError).join('\n')

  return `${VALIDATION_ERROR_MESSAGE_START}

${errorList}

Fix the Loop by modifying its nodes to resolve these errors.`
}

/**
 * Creates a formatted message for runtime errors that occurred while running the loop.
 */
export function createRuntimeErrorMessage(errors: RuntimeError[]): string {
  const errorList = errors.map(formatRuntimeError).join('\n')

  return `${RUNTIME_ERROR_MESSAGE_START}

${errorList}

Fix the Loop by modifying its nodes to resolve these errors.`
}

/**
 * Creates a formatted message for a single node error.
 */
export function createNodeErrorMessage(nodeId: string, error: string): string {
  return `${RUNTIME_ERROR_MESSAGE_START}

- ${error} (Node ${nodeId})

Fix the Loop by updating this node or other nodes upstream in the Loop.`
}

/**
 * Formats a validation error into a bullet point string.
 */
function formatValidationError(err: LoopValidationError): string {
  return `- ${err.error} (Nodes ${err.involvedNodes.join(', ')})`
}

/**
 * Formats a runtime error into a bullet point string.
 */
function formatRuntimeError(err: RuntimeError): string {
  return `- ${err.error} (Node ${err.nodeId})`
}

/**
 * Determines if a message content is an autofix message (validation or runtime error message).
 */
export function isAutofixMessage(messageContent?: string): boolean {
  if (!messageContent) return false

  return (
    messageContent.startsWith(VALIDATION_ERROR_MESSAGE_START) || messageContent.startsWith(RUNTIME_ERROR_MESSAGE_START)
  )
}
